// Loaded into the service worker generated by vite-plugin-pwa (workbox.importScripts).
// Shows the reminders the backend pushes and opens the board when one is tapped.

self.addEventListener('push', (event) => {
  let message = { title: 'Tarefas da Casa', body: '', url: '/' }
  try {
    message = { ...message, ...event.data.json() }
  } catch {
    if (event.data) message.body = event.data.text()
  }
  event.waitUntil(
    self.registration.showNotification(message.title, {
      body: message.body,
      icon: '/pwa-192x192.png',
      badge: '/pwa-192x192.png',
      data: { url: message.url },
    }),
  )
})

self.addEventListener('notificationclick', (event) => {
  event.notification.close()
  const url = (event.notification.data && event.notification.data.url) || '/'
  event.waitUntil(
    self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then((windows) => {
      const open = windows.find((client) => 'focus' in client)
      if (open) return open.focus().then((client) => client.navigate ? client.navigate(url) : client)
      return self.clients.openWindow(url)
    }),
  )
})
